Q: Can I access private members from outside the class without using friends? A: <p>Building on the work of <a href="https://stackoverflow.com/a/3173080/2776261">Johannes</a>, and using the technique from <a href="https://stackoverflow.com/a/67242467/2776261">김선달</a> to avoid having to specify the type of the private member, here's my answer (needs c++17):</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;string&gt;

template &lt;typename TagT, auto MemberT&gt;
struct Rob {
  friend constexpr auto get(TagT) { return MemberT; }
};

template &lt;typename UniqueT&gt;
struct MemberTag {
  friend constexpr auto get(MemberTag);  // The non-template friend is intentional
};

#define ENABLE_ACCESS_MEMBER(Class, Member) \
  using Class##_##Member = MemberTag&lt;class Class##_##Member##_&gt;; \
  template struct Rob&lt;Class##_##Member, &amp;Class::Member&gt;

#define ACCESS_MEMBER(Instance, Class, Member) \
  ((Instance).*get(Class##_##Member{}))

class Foo {
  int m_value = 42;
  std::string m_name = &quot;hello&quot;;
  double m_ratio = 3.14;

  int add(int a, int b) { return a + b; }
  std::string greet() const { return &quot;Hello from &quot; + m_name; }
};

ENABLE_ACCESS_MEMBER(Foo, m_value);
ENABLE_ACCESS_MEMBER(Foo, m_name);
ENABLE_ACCESS_MEMBER(Foo, m_ratio);
ENABLE_ACCESS_MEMBER(Foo, add);
ENABLE_ACCESS_MEMBER(Foo, greet);

int main() {
  Foo foo;

  // Read private members
  std::cout
    &lt;&lt; &quot;m_value = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_value) &lt;&lt; &quot;\n&quot;
    &lt;&lt; &quot;m_name  = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_name)  &lt;&lt; &quot;\n&quot;
    &lt;&lt; &quot;m_ratio = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_ratio) &lt;&lt; &quot;\n&quot;;

  // Call private functions
  std::cout
    &lt;&lt; &quot;add(3,4) = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, add)(3, 4) &lt;&lt; &quot;\n&quot;
    &lt;&lt; &quot;greet()  = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, greet)()   &lt;&lt; &quot;\n&quot;;

  // Write private members
  ACCESS_MEMBER(foo, Foo, m_value) = 100;
  ACCESS_MEMBER(foo, Foo, m_name)  = &quot;world&quot;;
  ACCESS_MEMBER(foo, Foo, m_ratio) = 2.71;

  std::cout
    &lt;&lt; &quot;\nAfter modification:\n&quot;
    &lt;&lt; &quot;m_value = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_value) &lt;&lt; &quot;\n&quot;
    &lt;&lt; &quot;m_name  = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_name)  &lt;&lt; &quot;\n&quot;
    &lt;&lt; &quot;m_ratio = &quot; &lt;&lt; ACCESS_MEMBER(foo, Foo, m_ratio) &lt;&lt; &quot;\n&quot;;

  return 0;
}
</code></pre>
<p>Expected output:</p>
<pre><code>m_value = 42
m_name  = hello
m_ratio = 3.14
add(3,4) = 7
greet()  = Hello from hello

After modification:
m_value = 100
m_name  = world
m_ratio = 2.71
</code></pre>
